create table public.project_work_items (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  project_id uuid not null references public.projects,
  request_id uuid not null,
  sub_lot_id uuid,
  catalog_version_id uuid,
  work_id uuid,
  work_code text check (work_code is null or work_code ~ '^btp_work_[a-z0-9_]+$'),
  label text not null check (length(btrim(label)) between 2 and 200),
  unit_code text check (unit_code is null or length(unit_code) <= 16),
  confirmation text not null default 'selected' check (confirmation in ('selected','to_confirm')),
  origin text not null check (origin in ('assistant','manual','import')),
  origin_ref uuid,
  ordinal integer not null default 0 check (ordinal >= 0),
  status text not null default 'active' check (status in ('active','removed')),
  revision integer not null default 1 check (revision > 0),
  created_by uuid references auth.users,
  removed_at timestamptz,
  removed_by uuid references auth.users,
  foreign key (request_id, project_id) references public.project_requests(id, project_id),
  foreign key (sub_lot_id, request_id, project_id) references public.request_sub_lots(id, request_id, project_id),
  foreign key (work_id, catalog_version_id) references public.btp_works(id, catalog_version_id),
  check ((work_id is null) = (catalog_version_id is null)),
  check ((work_id is null) = (work_code is null)),
  check ((status = 'removed') = (removed_at is not null)),
  unique (id, project_id)
);
create unique index project_work_items_origin_ref_uidx on public.project_work_items(origin_ref) where origin_ref is not null;
create index project_work_items_request_idx on public.project_work_items(request_id, status, ordinal);
create index project_work_items_project_idx on public.project_work_items(project_id, status);
create index project_work_items_work_idx on public.project_work_items(project_id, work_id) where status = 'active';

create table public.project_work_item_events (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  work_item_id uuid not null,
  project_id uuid not null,
  request_id uuid not null,
  request_version_id uuid references public.project_request_versions,
  event_type text not null check (event_type in ('created','updated','removed','imported','takeoff_linked')),
  item_revision integer not null check (item_revision > 0),
  actor_id uuid references auth.users,
  snapshot jsonb not null check (jsonb_typeof(snapshot) = 'object'),
  detail jsonb,
  foreign key (work_item_id, project_id) references public.project_work_items(id, project_id)
);
create index project_work_item_events_item_idx on public.project_work_item_events(work_item_id, created_at, id);
create index project_work_item_events_project_idx on public.project_work_item_events(project_id, created_at desc);
create trigger project_work_item_events_append_only before update or delete on public.project_work_item_events
  for each row execute function dao_private.append_only();

-- Identité figée : seul l'état courant évolue, jamais le chantier, le lot ni l'ouvrage.
create function dao_private.project_work_item_identity_guard() returns trigger
language plpgsql set search_path='' as $$
begin
  if TG_OP = 'DELETE' then raise exception using errcode='23514', message='Occurrence d''ouvrage : retrait tracé uniquement'; end if;
  if NEW.id <> OLD.id or NEW.project_id <> OLD.project_id or NEW.request_id <> OLD.request_id
     or NEW.work_id is distinct from OLD.work_id or NEW.catalog_version_id is distinct from OLD.catalog_version_id
     or NEW.origin <> OLD.origin or NEW.origin_ref is distinct from OLD.origin_ref or NEW.created_at <> OLD.created_at
     or (OLD.status = 'removed') then
    raise exception using errcode='23514', message='Occurrence d''ouvrage : identité immuable';
  end if;
  return NEW;
end; $$;
create trigger project_work_items_identity_guard before update or delete on public.project_work_items
  for each row execute function dao_private.project_work_item_identity_guard();

create table dao_private.project_work_item_command_receipts (
  actor_id uuid not null,
  idempotency_key text not null check (idempotency_key ~ '^[A-Za-z0-9._:-]{8,100}$'),
  action text not null,
  payload_sha256 text not null check (payload_sha256 ~ '^[0-9a-f]{64}$'),
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (actor_id, idempotency_key)
);

-- Journal de reprise (assistant, anciens métrés) : preuve des rattachements et des cas ambigus.
create table dao_private.project_work_item_migration_log (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  kind text not null check (kind in ('assistant_imported','assistant_work_not_in_catalog','takeoff_linked','takeoff_needs_assignment')),
  project_id uuid not null,
  subject_id uuid not null,
  detail jsonb not null default '{}'::jsonb,
  unique (kind, subject_id)
);

alter table public.project_work_items enable row level security;
alter table public.project_work_item_events enable row level security;
revoke all on public.project_work_items, public.project_work_item_events from public, anon, authenticated;
grant select, insert, update, delete on public.project_work_items, public.project_work_item_events to service_role;
revoke all on dao_private.project_work_item_command_receipts, dao_private.project_work_item_migration_log from public, anon, authenticated;
-- Lecture et écriture uniquement par RPC (Client propriétaire, gestionnaire affecté, Admin).
create policy project_work_items_private_read on public.project_work_items for select to authenticated
  using (dao_private.btp_estimate_access(project_id));
create policy project_work_item_events_private_read on public.project_work_item_events for select to authenticated
  using (dao_private.btp_estimate_access(project_id));

-- Version commerciale publiée : ouvrages retenus, sans aucune donnée privée.
alter table public.publication_requests add column works_scope jsonb
  check (works_scope is null or jsonb_typeof(works_scope) = 'array');

-- Lien des métrés vers l'occurrence du chantier.
alter table public.btp_takeoffs add column project_work_item_id uuid;
alter table public.btp_takeoffs add constraint btp_takeoffs_work_item_fk
  foreign key (project_work_item_id, project_id) references public.project_work_items(id, project_id);
alter table public.btp_takeoffs drop constraint btp_takeoffs_project_id_work_id_scope_key_key;
create unique index btp_takeoffs_legacy_scope_uidx on public.btp_takeoffs(project_id, work_id, scope_key) where project_work_item_id is null;
create unique index btp_takeoffs_work_item_scope_uidx on public.btp_takeoffs(project_work_item_id, scope_key) where project_work_item_id is not null;

