-- Lecture
-- ---------------------------------------------------------------------------------------------

-- État d'édition d'un lot pour la liste des ouvrages (même règle que les sous-lots officiels).
create function dao_private.project_work_item_lock_reason(p_request_id uuid) returns text
language sql stable security definer set search_path='' as $$
  select case
    when p.status <> 'draft' then 'project_not_draft'
    when not exists (select 1 from public.project_versions pv where pv.project_id = p.id and pv.status = 'draft') then 'project_in_review'
    when r.status <> 'open' then 'request_closed'
    when exists (select 1 from public.award_items ai where ai.request_id = r.id and ai.active) then 'awarded'
    when exists (select 1 from public.publication_requests pr join public.project_request_versions x on x.id = pr.request_version_id
                 where x.request_id = r.id) then 'published'
    else null end
  from public.project_requests r join public.projects p on p.id = r.project_id where r.id = p_request_id;
$$;

create function dao_private.project_work_item_json(p_item_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'id', i.id, 'requestId', i.request_id, 'subLotId', i.sub_lot_id, 'workId', i.work_id, 'workCode', i.work_code,
    'catalogVersionId', i.catalog_version_id, 'catalogVersionCode', cv.code, 'label', i.label, 'unitCode', i.unit_code,
    'custom', i.work_id is null, 'confirmation', i.confirmation, 'origin', i.origin, 'ordinal', i.ordinal,
    'status', i.status, 'revision', i.revision, 'createdAt', i.created_at, 'updatedAt', i.updated_at,
    'catalogPath', case when w.id is null then null else jsonb_build_object('lot', cl.label_fr, 'subLot', cs.label_fr) end,
    'measurable', i.work_id is not null and exists (
      select 1 from public.btp_measurement_templates m join public.btp_catalog_versions v on v.id = m.catalog_version_id
      join public.btp_works pw on pw.id = m.work_id and pw.catalog_version_id = m.catalog_version_id
      where m.work_id = i.work_id and m.active and pw.active and v.status = 'published'),
    'takeoffs', (select count(*) from public.btp_takeoffs t where t.project_work_item_id = i.id),
    'validatedTakeoffs', (select count(*) from public.btp_takeoffs t where t.project_work_item_id = i.id and t.validated_revision is not null))
  from public.project_work_items i
  left join public.btp_catalog_versions cv on cv.id = i.catalog_version_id
  left join public.btp_works w on w.id = i.work_id and w.catalog_version_id = i.catalog_version_id
  left join public.btp_sub_lots cs on cs.id = w.sub_lot_id and cs.catalog_version_id = w.catalog_version_id
  left join public.btp_lots cl on cl.id = cs.lot_id and cl.catalog_version_id = cs.catalog_version_id
  where i.id = p_item_id;
$$;

create function dao_private.project_work_items_snapshot_v1(p_project_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_catalog jsonb;
begin
  if auth.uid() is null or p_project_id is null or not dao_private.btp_estimate_access(p_project_id) then
    raise exception using errcode='42501', message='project work items access required';
  end if;
  select jsonb_build_object('id', v.id, 'code', v.code) into v_catalog from public.btp_catalog_versions v
    where v.status = 'published' and v.country_code = 'TN' order by v.effective_from desc limit 1;
  return jsonb_build_object(
    'projectId', p_project_id,
    'canEdit', dao_private.owner(p_project_id),
    'catalogVersion', v_catalog,
    'lots', (select coalesce(jsonb_agg(jsonb_build_object(
        'requestId', r.id, 'requestVersionId', rv.id, 'requestVersion', rv.version_no, 'title', rv.title, 'tradeId', rv.trade_id,
        'status', r.status, 'lockReason', dao_private.project_work_item_lock_reason(r.id),
        'subLots', (select coalesce(jsonb_agg(jsonb_build_object('id', s.sub_lot_id, 'title', s.title, 'ordinal', s.ordinal) order by s.ordinal), '[]'::jsonb)
          from public.request_sub_lot_versions s where s.request_version_id = rv.id),
        'items', (select coalesce(jsonb_agg(dao_private.project_work_item_json(i.id) || jsonb_build_object('subLotCurrent',
              i.sub_lot_id is null or exists (select 1 from public.request_sub_lot_versions s where s.request_version_id = rv.id and s.sub_lot_id = i.sub_lot_id))
            order by i.ordinal, i.created_at, i.id), '[]'::jsonb)
          from public.project_work_items i where i.request_id = r.id and i.status = 'active')
      ) order by r.created_at, r.id), '[]'::jsonb)
      from public.project_requests r
      join lateral (select x.* from public.project_request_versions x where x.request_id = r.id order by x.version_no desc limit 1) rv on true
      where r.project_id = p_project_id and r.status <> 'withdrawn'),
    'removedCount', (select count(*) from public.project_work_items i where i.project_id = p_project_id and i.status = 'removed'));
end; $$;

-- Historique d'une occurrence (traces conservées, y compris après retrait).
create function dao_private.project_work_item_history_v1(p_item_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_project uuid;
begin
  select project_id into v_project from public.project_work_items where id = p_item_id;
  if v_project is null then raise exception using errcode='P0002', message='work item not found'; end if;
  if auth.uid() is null or not dao_private.btp_estimate_access(v_project) then
    raise exception using errcode='42501', message='project work items access required';
  end if;
  return jsonb_build_object('item', dao_private.project_work_item_json(p_item_id), 'events',
    (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'type', e.event_type, 'revision', e.item_revision, 'requestVersionId', e.request_version_id,
      'actorId', e.actor_id, 'snapshot', e.snapshot, 'detail', e.detail, 'createdAt', e.created_at) order by e.created_at, e.id), '[]'::jsonb)
     from public.project_work_item_events e where e.work_item_id = p_item_id));
end; $$;

