-- Écriture
-- ---------------------------------------------------------------------------------------------

create function dao_private.project_work_item_event(p_item public.project_work_items, p_type text, p_actor uuid, p_detail jsonb default null)
returns void language sql security definer set search_path='' as $$
  insert into public.project_work_item_events(work_item_id, project_id, request_id, request_version_id, event_type, item_revision, actor_id, snapshot, detail)
  values (p_item.id, p_item.project_id, p_item.request_id,
    (select x.id from public.project_request_versions x where x.request_id = p_item.request_id order by x.version_no desc limit 1),
    p_type, p_item.revision, p_actor, to_jsonb(p_item), p_detail);
$$;

create function dao_private.project_work_item_command_v1(p_action text, p_input jsonb, p_idempotency_key text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid := auth.uid(); v_hash text; prior dao_private.project_work_item_command_receipts; result jsonb;
  v_request public.project_requests; v_project_id uuid; v_reason text; v_item public.project_work_items; v_entry jsonb;
  v_sub uuid; v_work uuid; v_label text; v_confirmation text; v_version public.btp_catalog_versions;
  w_id uuid; w_code text; w_label text; w_unit text; v_ordinal integer; v_takeoff public.btp_takeoffs; v_expected integer;
  v_created uuid[] := '{}';
begin
  if actor is null or not dao_private.account_active(actor) then
    raise exception using errcode='42501', message='active authentication required';
  end if;
  if p_action not in ('add','update','remove','link_takeoff') or p_input is null or jsonb_typeof(p_input) <> 'object'
     or coalesce(p_idempotency_key, '') !~ '^[A-Za-z0-9._:-]{8,100}$' then
    raise exception using errcode='22023', message='invalid work item command';
  end if;
  v_hash := encode(sha256(convert_to(p_action || ':' || p_input::text, 'UTF8')), 'hex');
  perform pg_advisory_xact_lock(hashtextextended(actor::text || ':work-item:' || p_idempotency_key, 0));
  select * into prior from dao_private.project_work_item_command_receipts where actor_id = actor and idempotency_key = p_idempotency_key;
  if found then
    if prior.action <> p_action or prior.payload_sha256 <> v_hash then raise exception using errcode='22023', message='idempotency key already used'; end if;
    return prior.result;
  end if;

  if p_action = 'link_takeoff' then
    if exists (select 1 from jsonb_object_keys(p_input) k where k not in ('takeoffId','itemId')) then
      raise exception using errcode='22023', message='unexpected field'; end if;
    begin
      select * into v_takeoff from public.btp_takeoffs where id = (p_input->>'takeoffId')::uuid for update;
      select * into v_item from public.project_work_items where id = (p_input->>'itemId')::uuid for update;
    exception when invalid_text_representation then raise exception using errcode='22023', message='invalid identifier'; end;
    if v_takeoff.id is null or v_item.id is null then raise exception using errcode='P0002', message='takeoff or work item not found'; end if;
    if not (dao_private.owner(v_takeoff.project_id) or dao_private.manages_project(v_takeoff.project_id)) then
      raise exception using errcode='42501', message='project takeoff write access required'; end if;
    if v_item.project_id <> v_takeoff.project_id or v_item.status <> 'active' or v_item.work_id is distinct from v_takeoff.work_id then
      raise exception using errcode='22023', message='work item does not match this takeoff'; end if;
    if v_takeoff.project_work_item_id is not null then
      raise exception using errcode='23514', message='takeoff already linked'; end if;
    update public.btp_takeoffs set project_work_item_id = v_item.id where id = v_takeoff.id;
    perform dao_private.project_work_item_event(v_item, 'takeoff_linked', actor, jsonb_build_object('takeoffId', v_takeoff.id, 'scopeKey', v_takeoff.scope_key));
    v_project_id := v_item.project_id;
  else
    if p_action = 'add' then
      if exists (select 1 from jsonb_object_keys(p_input) k where k not in ('requestId','items'))
         or jsonb_typeof(p_input->'items') is distinct from 'array' or jsonb_array_length(p_input->'items') not between 1 and 50 then
        raise exception using errcode='22023', message='invalid work item list'; end if;
      begin select * into v_request from public.project_requests where id = (p_input->>'requestId')::uuid;
      exception when invalid_text_representation then raise exception using errcode='22023', message='invalid request id'; end;
    else
      if exists (select 1 from jsonb_object_keys(p_input) k where k not in ('itemId','expectedRevision','subLotId','confirmation','label')) then
        raise exception using errcode='22023', message='unexpected field'; end if;
      begin
        select * into v_item from public.project_work_items where id = (p_input->>'itemId')::uuid;
        v_expected := (p_input->>'expectedRevision')::integer;
      exception when invalid_text_representation then raise exception using errcode='22023', message='invalid identifier'; end;
      if v_item.id is null then raise exception using errcode='P0002', message='work item not found'; end if;
      select * into v_request from public.project_requests where id = v_item.request_id;
    end if;
    if v_request.id is null then raise exception using errcode='P0002', message='request not found'; end if;
    v_project_id := v_request.project_id;
    if not dao_private.owner(v_project_id) then raise exception using errcode='42501', message='project owner required'; end if;
    -- Même verrou que la publication : aucune course entre l'instantané publié et une modification.
    perform 1 from public.projects where id = v_project_id for update;
    perform 1 from public.project_requests where id = v_request.id for update;
    v_reason := dao_private.project_work_item_lock_reason(v_request.id);
    if v_reason is not null then
      raise exception using errcode='23514', message='published, awarded or submitted lots cannot change their works', hint='work_items_locked:' || v_reason;
    end if;

    if p_action = 'add' then
      select * into v_version from public.btp_catalog_versions where status = 'published' and country_code = 'TN' order by effective_from desc limit 1;
      for v_entry in select value from jsonb_array_elements(p_input->'items') loop
        if jsonb_typeof(v_entry) <> 'object' or exists (select 1 from jsonb_object_keys(v_entry) k where k not in ('subLotId','workId','label','confirmation')) then
          raise exception using errcode='22023', message='invalid work item'; end if;
        v_sub := null; v_work := null;
        begin
          v_sub := nullif(v_entry->>'subLotId', '')::uuid;
          v_work := nullif(v_entry->>'workId', '')::uuid;
        exception when invalid_text_representation then raise exception using errcode='22023', message='invalid identifier'; end;
        v_confirmation := coalesce(nullif(v_entry->>'confirmation', ''), 'selected');
        if v_confirmation not in ('selected','to_confirm') then raise exception using errcode='22023', message='invalid confirmation'; end if;
        if v_sub is not null and not exists (
            select 1 from public.request_sub_lot_versions s
            where s.sub_lot_id = v_sub and s.request_id = v_request.id
              and s.request_version_id = (select x.id from public.project_request_versions x where x.request_id = v_request.id order by x.version_no desc limit 1)) then
          raise exception using errcode='22023', message='sub-lot is not part of this lot'; end if;
        w_id := null; w_code := null; w_label := null; w_unit := null;
        if v_work is not null then
          if v_version.id is null then raise exception using errcode='P0002', message='no published BTP catalogue'; end if;
          select w.id, w.code, w.label_fr, w.unit_code into w_id, w_code, w_label, w_unit from public.btp_works w
            where w.id = v_work and w.catalog_version_id = v_version.id and w.active;
          if w_id is null then raise exception using errcode='22023', message='work is not in the published catalogue'; end if;
          if v_entry ? 'label' then raise exception using errcode='22023', message='a catalogue work keeps its catalogue label'; end if;
          v_label := w_label;
        else
          v_label := btrim(regexp_replace(coalesce(v_entry->>'label', ''), '\s+', ' ', 'g'));
          if length(v_label) not between 2 and 200 or v_label ~ '[<>{}]' then
            raise exception using errcode='22023', message='custom work label required (2 to 200 characters)'; end if;
        end if;
        select coalesce(max(ordinal), -1) + 1 into v_ordinal from public.project_work_items where request_id = v_request.id;
        insert into public.project_work_items(project_id, request_id, sub_lot_id, catalog_version_id, work_id, work_code, label, unit_code,
          confirmation, origin, ordinal, created_by)
        values (v_project_id, v_request.id, v_sub, case when w_id is null then null else v_version.id end, w_id, w_code, v_label, w_unit,
          v_confirmation, 'manual', v_ordinal, actor)
        returning * into v_item;
        perform dao_private.project_work_item_event(v_item, 'created', actor);
        v_created := v_created || v_item.id;
      end loop;
    else
      select * into v_item from public.project_work_items where id = v_item.id for update;
      if v_item.status <> 'active' then raise exception using errcode='23514', message='work item already removed'; end if;
      if v_expected is null or v_expected <> v_item.revision then raise exception using errcode='40001', message='work item changed'; end if;
      if p_action = 'remove' then
        if exists (select 1 from public.btp_takeoffs t where t.project_work_item_id = v_item.id) then
          raise exception using errcode='23514', message='work item has takeoffs', hint='work_item_has_takeoffs'; end if;
        update public.project_work_items set status = 'removed', removed_at = now(), removed_by = actor, revision = revision + 1, updated_at = now()
          where id = v_item.id returning * into v_item;
        perform dao_private.project_work_item_event(v_item, 'removed', actor);
      else
        v_sub := v_item.sub_lot_id; v_confirmation := v_item.confirmation; v_label := v_item.label;
        if p_input ? 'subLotId' then
          begin v_sub := nullif(p_input->>'subLotId', '')::uuid;
          exception when invalid_text_representation then raise exception using errcode='22023', message='invalid identifier'; end;
          if v_sub is not null and not exists (
              select 1 from public.request_sub_lot_versions s where s.sub_lot_id = v_sub and s.request_id = v_item.request_id
                and s.request_version_id = (select x.id from public.project_request_versions x where x.request_id = v_item.request_id order by x.version_no desc limit 1)) then
            raise exception using errcode='22023', message='sub-lot is not part of this lot'; end if;
        end if;
        if p_input ? 'confirmation' then
          v_confirmation := p_input->>'confirmation';
          if v_confirmation is null or v_confirmation not in ('selected','to_confirm') then raise exception using errcode='22023', message='invalid confirmation'; end if;
        end if;
        if p_input ? 'label' then
          if v_item.work_id is not null then raise exception using errcode='22023', message='a catalogue work keeps its catalogue label'; end if;
          v_label := btrim(regexp_replace(coalesce(p_input->>'label', ''), '\s+', ' ', 'g'));
          if length(v_label) not between 2 and 200 or v_label ~ '[<>{}]' then raise exception using errcode='22023', message='custom work label required (2 to 200 characters)'; end if;
        end if;
        if v_sub is not distinct from v_item.sub_lot_id and v_confirmation = v_item.confirmation and v_label = v_item.label then
          raise exception using errcode='22023', message='nothing to change'; end if;
        update public.project_work_items set sub_lot_id = v_sub, confirmation = v_confirmation, label = v_label,
          revision = revision + 1, updated_at = now() where id = v_item.id returning * into v_item;
        perform dao_private.project_work_item_event(v_item, 'updated', actor);
      end if;
    end if;
  end if;

  result := dao_private.project_work_items_snapshot_v1(v_project_id) || jsonb_build_object('createdIds', to_jsonb(v_created));
  insert into dao_private.project_work_item_command_receipts(actor_id, idempotency_key, action, payload_sha256, result)
  values (actor, p_idempotency_key, p_action, v_hash, result);
  return result;
end; $$;

-- Instantané commercial à la publication du lot : ouvrages retenus seulement, sans données privées.
create function dao_private.publication_works_snapshot() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_request uuid;
begin
  select request_id into v_request from public.project_request_versions where id = NEW.request_version_id;
  NEW.works_scope := (select coalesce(jsonb_agg(jsonb_build_object(
      'id', i.id, 'label', i.label, 'unitCode', i.unit_code, 'workCode', i.work_code, 'custom', i.work_id is null,
      'toConfirm', i.confirmation = 'to_confirm',
      'subLotId', case when exists (select 1 from public.request_sub_lot_versions s where s.request_version_id = NEW.request_version_id and s.sub_lot_id = i.sub_lot_id) then i.sub_lot_id end)
    order by i.ordinal, i.created_at, i.id), '[]'::jsonb)
    from public.project_work_items i where i.request_id = v_request and i.status = 'active');
  return NEW;
end; $$;
create trigger publication_works_snapshot before insert on public.publication_requests
  for each row execute function dao_private.publication_works_snapshot();

-- ---------------------------------------------------------------------------------------------
-- Reprise : assistant (#543) et anciens métrés (#548/#560)
-- ---------------------------------------------------------------------------------------------

create function dao_private.import_assistant_work_items_v1(p_project_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare l record; v_item public.project_work_items; w_id uuid; w_version uuid; w_code text; w_unit text; v_count integer := 0; v_custom integer := 0;
begin
  for l in select sl.*, d.owner_id from public.project_assistant_scope_links sl
      join public.project_assistant_drafts d on d.id = sl.draft_id
      where (p_project_id is null or sl.project_id = p_project_id) and sl.item_kind = 'work'
        and not exists (select 1 from public.project_work_items i where i.origin_ref = sl.id)
      order by sl.project_id, sl.request_id, sl.created_at, sl.id loop
    w_id := null; w_version := null; w_code := null; w_unit := null;
    if l.item_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      select w.id, w.catalog_version_id, w.code, w.unit_code into w_id, w_version, w_code, w_unit
        from public.btp_works w join public.btp_catalog_versions v on v.id = w.catalog_version_id
        where w.id = l.item_id::uuid
        order by (v.code = l.referential_version) desc, (v.status = 'published') desc, v.effective_from desc limit 1;
    end if;
    insert into public.project_work_items(project_id, request_id, sub_lot_id, catalog_version_id, work_id, work_code, label, unit_code,
      confirmation, origin, origin_ref, ordinal, created_by, created_at, updated_at)
    values (l.project_id, l.request_id, l.sub_lot_id, w_version, w_id, w_code,
      case when length(btrim(l.item_label)) >= 2 then left(btrim(l.item_label), 200) else 'Ouvrage ' || l.item_code end,
      coalesce(w_unit, l.unit), case when l.relevance in ('verify','unusual') then 'to_confirm' else 'selected' end,
      'assistant', l.id, (select coalesce(max(i.ordinal), -1) + 1 from public.project_work_items i where i.request_id = l.request_id),
      l.owner_id, l.created_at, l.created_at)
    returning * into v_item;
    perform dao_private.project_work_item_event(v_item, 'imported', null,
      jsonb_build_object('source', 'project_assistant_scope_links', 'linkId', l.id, 'draftId', l.draft_id, 'itemId', l.item_id, 'referentialVersion', l.referential_version));
    insert into dao_private.project_work_item_migration_log(kind, project_id, subject_id, detail)
    values (case when w_id is null then 'assistant_work_not_in_catalog' else 'assistant_imported' end, l.project_id, l.id,
      jsonb_build_object('workItemId', v_item.id, 'itemId', l.item_id, 'requestId', l.request_id, 'subLotId', l.sub_lot_id))
    on conflict (kind, subject_id) do nothing;
    v_count := v_count + 1;
    if w_id is null then v_custom := v_custom + 1; end if;
  end loop;
  return jsonb_build_object('imported', v_count, 'notInCatalog', v_custom);
end; $$;

-- Rattache un ancien métré seulement si une seule occurrence active du même ouvrage existe.
create function dao_private.link_legacy_takeoffs_v1(p_project_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t record; v_count integer; v_candidate uuid; v_linked integer := 0; v_pending integer := 0; v_item public.project_work_items;
begin
  for t in select * from public.btp_takeoffs where project_work_item_id is null and (p_project_id is null or project_id = p_project_id)
      order by created_at, id loop
    select count(*), (array_agg(i.id order by i.id))[1] into v_count, v_candidate from public.project_work_items i
      where i.project_id = t.project_id and i.work_id = t.work_id and i.status = 'active';
    if v_count = 1 and not exists (select 1 from public.btp_takeoffs x where x.project_work_item_id = v_candidate and x.scope_key = t.scope_key) then
      update public.btp_takeoffs set project_work_item_id = v_candidate where id = t.id;
      select * into v_item from public.project_work_items where id = v_candidate;
      perform dao_private.project_work_item_event(v_item, 'takeoff_linked', null,
        jsonb_build_object('takeoffId', t.id, 'scopeKey', t.scope_key, 'basis', 'single_matching_occurrence'));
      insert into dao_private.project_work_item_migration_log(kind, project_id, subject_id, detail)
      values ('takeoff_linked', t.project_id, t.id, jsonb_build_object('workItemId', v_candidate, 'workId', t.work_id, 'scopeKey', t.scope_key))
      on conflict (kind, subject_id) do nothing;
      v_linked := v_linked + 1;
    else
      insert into dao_private.project_work_item_migration_log(kind, project_id, subject_id, detail)
      values ('takeoff_needs_assignment', t.project_id, t.id, jsonb_build_object('workId', t.work_id, 'scopeKey', t.scope_key, 'candidates', v_count,
        'reason', case when v_count = 0 then 'no_occurrence' when v_count > 1 then 'ambiguous' else 'scope_conflict' end))
      on conflict (kind, subject_id) do update set detail = excluded.detail;
      v_pending := v_pending + 1;
    end if;
  end loop;
  return jsonb_build_object('linked', v_linked, 'needsAssignment', v_pending);
end; $$;

-- Métrés : rattachement à l'occurrence, lecture privée.
create or replace function dao_private.btp_takeoff_payload(p_takeoff_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'id',t.id,'projectId',t.project_id,'catalogVersionId',t.catalog_version_id,'workId',t.work_id,'templateId',t.template_id,
    'workItemId',t.project_work_item_id,'scopeKey',t.scope_key,'label',t.label,'status',t.status,'currentRevision',t.current_revision,'validatedRevision',t.validated_revision,
    'current',(select jsonb_build_object('id',r.id,'revision',r.revision,'status',r.calculation_status,'inputs',r.canonical_inputs,
      'formula',r.formula_snapshot,'justification',r.justification,'inputSha256',r.input_sha256,'resultSha256',r.result_sha256,
      'createdBy',r.created_by,'createdAt',r.created_at) from public.btp_takeoff_revisions r where r.takeoff_id=t.id and r.revision=t.current_revision),
    'validated',(select jsonb_build_object('id',r.id,'revision',r.revision,'status',r.calculation_status,'inputs',r.canonical_inputs,
      'formula',r.formula_snapshot,'justification',r.justification,'inputSha256',r.input_sha256,'resultSha256',r.result_sha256,
      'createdBy',r.created_by,'createdAt',r.created_at) from public.btp_takeoff_revisions r where r.takeoff_id=t.id and r.revision=t.validated_revision),
    'history',(select coalesce(jsonb_agg(jsonb_build_object('revision',r.revision,'status',r.calculation_status,
      'result',r.justification->'result','createdBy',r.created_by,'createdAt',r.created_at) order by r.revision desc),'[]'::jsonb)
      from public.btp_takeoff_revisions r where r.takeoff_id=t.id),
    'events',(select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id',e.id,'revision',e.revision,'type',e.event_type,
      'actorId',e.actor_id,'note',e.note,'validationBasis',e.validation_basis,'createdAt',e.created_at)) order by e.created_at,e.id),'[]'::jsonb)
      from public.btp_takeoff_events e where e.takeoff_id=t.id)
  ) from public.btp_takeoffs t where t.id=p_takeoff_id;
$$;

create or replace function dao_private.btp_takeoff_command_v1(p_action text,p_input jsonb,p_idempotency_key text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare actor uuid:=auth.uid(); payload_hash text; prior dao_private.btp_takeoff_command_receipts; result jsonb;
  v_project_id uuid;v_work_id uuid;v_takeoff_id uuid;template record;takeoff public.btp_takeoffs;v_revision integer;expected integer;
  v_scope_key text;v_label text;canonical jsonb;required_name text;missing text[]:='{}';entry jsonb;expected_unit text;
  original jsonb;conversion_factor numeric;
  calc record;rounded numeric;formula jsonb;justification jsonb;input_hash text;result_hash text;note text;basis text;
  v_item_id uuid;v_item public.project_work_items;
begin
  if actor is null or p_action not in ('calculate','submit','validate') or p_idempotency_key!~'^[A-Za-z0-9._:-]{8,100}$' or jsonb_typeof(p_input)<>'object' then
    raise exception using errcode='22023',message='invalid takeoff command';
  end if;
  payload_hash:=encode(sha256(convert_to(p_action||':'||p_input::text,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':btp-takeoff:'||p_idempotency_key,0));
  select * into prior from dao_private.btp_takeoff_command_receipts where actor_id=actor and idempotency_key=p_idempotency_key;
  if found then
    if prior.action<>p_action or prior.payload_sha256<>payload_hash then raise exception using errcode='22023',message='idempotency key already used'; end if;
    return prior.result;
  end if;

  if p_action='calculate' then
    begin
      v_project_id:=(p_input->>'projectId')::uuid;v_work_id:=(p_input->>'workId')::uuid;
      v_takeoff_id:=nullif(p_input->>'takeoffId','')::uuid;expected:=nullif(p_input->>'expectedRevision','')::integer;
      v_item_id:=nullif(p_input->>'workItemId','')::uuid;
    exception when others then raise exception using errcode='22023',message='invalid project, work or revision'; end;
    if not (dao_private.owner(v_project_id) or dao_private.manages_project(v_project_id)) then raise exception using errcode='42501',message='project takeoff write access required'; end if;
    v_scope_key:=coalesce(p_input->>'scopeKey','');v_label:=btrim(coalesce(p_input->>'label',''));canonical:=coalesce(p_input->'canonicalInputs','{}'::jsonb);
    if v_scope_key!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$' or length(v_label) not between 1 and 160 or jsonb_typeof(canonical)<>'object' then
      raise exception using errcode='22023',message='invalid takeoff scope or inputs';
    end if;
    select m.id,m.catalog_version_id,m.output_unit_code,m.input_schema,m.formula_ast,m.rounding_scale,m.assumptions_fr,m.source_ref,
      w.code work_code,w.label_fr work_label into template
    from public.btp_measurement_templates m join public.btp_works w on w.id=m.work_id and w.catalog_version_id=m.catalog_version_id
      join public.btp_catalog_versions v on v.id=m.catalog_version_id
    where m.work_id=v_work_id and m.active and w.active and v.status='published' order by v.effective_from desc limit 1;
    if not found then raise exception using errcode='P0002',message='published measurement template not found'; end if;
    for required_name in select jsonb_array_elements_text(template.input_schema->'required') loop
      if not (canonical ? required_name) then missing:=array_append(missing,required_name);continue; end if;
      entry:=canonical->required_name;expected_unit:=dao_private.btp_takeoff_expected_unit(required_name);
      if jsonb_typeof(entry)<>'object' or expected_unit is null or entry->>'unit'<>expected_unit
        or coalesce(entry->>'value','')!~'^(0|[1-9][0-9]{0,8})(\.[0-9]{1,6})?$'
        or jsonb_typeof(entry->'source')<>'object' or entry->'source'->>'kind' not in ('manual','document','survey','bim_import')
        or length(btrim(coalesce(entry->'source'->>'reference',''))) not between 1 and 300
        or jsonb_typeof(entry->'original')<>'object'
        or coalesce(entry->'original'->>'value','')!~'^(0|[1-9][0-9]{0,8})(\.[0-9]{1,6})?$' then
        raise exception using errcode='22023',message='invalid canonical measurement input';
      end if;
      original:=entry->'original';
      conversion_factor:=case
        when expected_unit='m' and original->>'unit'='m' then 1
        when expected_unit='m' and original->>'unit'='cm' then 0.01
        when expected_unit='m' and original->>'unit'='mm' then 0.001
        when expected_unit='m2' and original->>'unit'='m2' then 1
        when expected_unit='m2' and original->>'unit'='cm2' then 0.0001
        when expected_unit='m2' and original->>'unit'='mm2' then 0.000001
        when expected_unit='m3' and original->>'unit'='m3' then 1
        when expected_unit='m3' and original->>'unit'='l' then 0.001
        when expected_unit='m3' and original->>'unit'='cm3' then 0.000001
        when expected_unit='unit' and original->>'unit'='unit' then 1
        else null end;
      if conversion_factor is null or (original->>'value')::numeric*conversion_factor<>(entry->>'value')::numeric then
        raise exception using errcode='22023',message='canonical measurement does not match original input';
      end if;
    end loop;
    if exists(select 1 from jsonb_object_keys(canonical) k
      where not (coalesce(template.input_schema->'properties','{}'::jsonb) ? k or template.input_schema->'required' ? k)) then
      raise exception using errcode='22023',message='unsupported measurement input';
    end if;
    if v_takeoff_id is null then
      -- #577 : tout nouveau métré est rattaché à une occurrence d'ouvrage du chantier (lot/sous-lot réels).
      if v_item_id is null then raise exception using errcode='22023',message='project work item required'; end if;
      select * into v_item from public.project_work_items i where i.id=v_item_id and i.project_id=v_project_id;
      if not found or v_item.status<>'active' then raise exception using errcode='P0002',message='project work item not found'; end if;
      if v_item.work_id is distinct from v_work_id then raise exception using errcode='22023',message='work item does not match this work'; end if;
      insert into public.btp_takeoffs(project_id,catalog_version_id,work_id,template_id,scope_key,label,created_by,project_work_item_id)
      values(v_project_id,template.catalog_version_id,v_work_id,template.id,v_scope_key,v_label,actor,v_item_id)
      returning * into takeoff;
    else
      select * into takeoff from public.btp_takeoffs t where t.id=v_takeoff_id and t.project_id=v_project_id for update;
      if not found then raise exception using errcode='P0002',message='takeoff not found'; end if;
      if takeoff.work_id<>v_work_id or (v_item_id is not null and takeoff.project_work_item_id is distinct from v_item_id) or expected is null or expected<>takeoff.current_revision then raise exception using errcode='40001',message='takeoff revision changed'; end if;
    end if;
    v_revision:=takeoff.current_revision+1;
    formula:=jsonb_build_object('templateId',template.id,'catalogVersionId',template.catalog_version_id,'workCode',template.work_code,
      'outputUnitCode',template.output_unit_code,'ast',template.formula_ast,'roundingScale',template.rounding_scale,
      'assumptions',template.assumptions_fr,'sourceRef',template.source_ref,'engineVersion','dao-takeoff-v1');
    if cardinality(missing)>0 then
      justification:=jsonb_build_object('status','insufficient_data','missingFields',to_jsonb(missing),
        'questions',(select jsonb_agg('Renseignez '||x||' en '||dao_private.btp_takeoff_expected_unit(x)||' avec sa provenance.' order by x) from unnest(missing) x),
        'canonicalInputs',canonical,
        'conversions',(select coalesce(jsonb_agg(jsonb_build_object('field',x.key,'from',x.value->'original',
          'to',jsonb_build_object('value',x.value->>'value','unit',x.value->>'unit'),'source',x.value->'source') order by x.key),'[]'::jsonb)
          from jsonb_each(canonical) x),
        'catalogVersionId',template.catalog_version_id,'templateId',template.id,'engineVersion','dao-takeoff-v1');
    else
      select * into calc from dao_private.btp_takeoff_eval(template.formula_ast,canonical);
      if calc.dimension<>template.output_unit_code or calc.value<=0 or calc.value>1000000000000000 then
        raise exception using errcode='22023',message='calculated quantity is invalid or out of range';
      end if;
      rounded:=round(calc.value,template.rounding_scale);
      justification:=jsonb_build_object('status','calculated','formula',template.formula_ast,'canonicalInputs',canonical,
        'conversions',(select coalesce(jsonb_agg(jsonb_build_object('field',x.key,'from',x.value->'original',
          'to',jsonb_build_object('value',x.value->>'value','unit',x.value->>'unit'),'source',x.value->'source') order by x.key),'[]'::jsonb)
          from jsonb_each(canonical) x),'steps',calc.steps,
        'rawResult',calc.value,'result',jsonb_build_object('value',rounded,'unit',template.output_unit_code,'roundingScale',template.rounding_scale),
        'catalogVersionId',template.catalog_version_id,'templateId',template.id,'workId',v_work_id,'engineVersion','dao-takeoff-v1',
        'assumptions',template.assumptions_fr,'sourceRef',template.source_ref);
    end if;
    input_hash:=encode(sha256(convert_to(canonical::text,'UTF8')),'hex');result_hash:=encode(sha256(convert_to(justification::text,'UTF8')),'hex');
    insert into public.btp_takeoff_revisions(takeoff_id,revision,calculation_status,canonical_inputs,formula_snapshot,justification,input_sha256,result_sha256,created_by)
    values(takeoff.id,v_revision,case when cardinality(missing)>0 then 'insufficient_data' else 'calculated' end,canonical,formula,justification,input_hash,result_hash,actor);
    if takeoff.status='validated' then
      insert into public.btp_takeoff_events(takeoff_id,revision,event_type,actor_id,note) values(takeoff.id,v_revision,'validation_invalidated',actor,'Nouvelle révision ; résultat validé précédent conservé.');
    end if;
    update public.btp_takeoffs set current_revision=v_revision,status='draft',label=v_label,updated_at=now() where id=takeoff.id;
    insert into public.btp_takeoff_events(takeoff_id,revision,event_type,actor_id) values(takeoff.id,v_revision,case when cardinality(missing)>0 then 'insufficient_data' else 'calculated' end,actor);
    result:=dao_private.btp_takeoff_payload(takeoff.id);
  else
    begin v_takeoff_id:=(p_input->>'takeoffId')::uuid;expected:=(p_input->>'expectedRevision')::integer;
    exception when others then raise exception using errcode='22023',message='invalid takeoff or revision'; end;
    note:=nullif(btrim(coalesce(p_input->>'note','')),'');
    if note is not null and length(note)>1000 then raise exception using errcode='22023',message='note too long'; end if;
    select * into takeoff from public.btp_takeoffs t where t.id=v_takeoff_id for update;
    if not found then raise exception using errcode='P0002',message='takeoff not found'; end if;
    if expected<>takeoff.current_revision then raise exception using errcode='40001',message='takeoff revision changed'; end if;
    if p_action='submit' then
      if not (dao_private.owner(takeoff.project_id) or dao_private.manages_project(takeoff.project_id)) then raise exception using errcode='42501',message='takeoff submit access required'; end if;
      if takeoff.status<>'draft' or not exists(select 1 from public.btp_takeoff_revisions r where r.takeoff_id=takeoff.id and r.revision=expected and r.calculation_status='calculated') then
        raise exception using errcode='22023',message='only a calculated draft can be submitted';
      end if;
      update public.btp_takeoffs set status='submitted',updated_at=now() where id=takeoff.id;
      insert into public.btp_takeoff_events(takeoff_id,revision,event_type,actor_id,note) values(takeoff.id,expected,'submitted',actor,note);
    else
      -- #556 §5.1 : gestionnaire affecté ou Admin, ou Client propriétaire si le réglage l'autorise
      -- (plateforme ou exception chantier, résolu côté base au moment de la validation).
      if dao_private.manages_project(takeoff.project_id) then basis:='manager';
      elsif dao_private.owner(takeoff.project_id)
        and coalesce((dao_private.resolve_setting('takeoffs.client_validation',actor,'client',takeoff.project_id)->>'value')::boolean,false) then
        basis:='client_setting';
      else raise exception using errcode='42501',message='assigned manager validation required'; end if;
      if takeoff.status<>'submitted' then raise exception using errcode='22023',message='only a submitted takeoff can be validated'; end if;
      update public.btp_takeoffs set status='validated',validated_revision=expected,updated_at=now() where id=takeoff.id;
      insert into public.btp_takeoff_events(takeoff_id,revision,event_type,actor_id,note,validation_basis) values(takeoff.id,expected,'validated',actor,note,basis);
    end if;
    result:=dao_private.btp_takeoff_payload(takeoff.id);
  end if;
  insert into dao_private.btp_takeoff_command_receipts(actor_id,idempotency_key,action,payload_sha256,result)
  values(actor,p_idempotency_key,p_action,payload_hash,result);
  return result;
end;
$$;

create or replace function dao_private.btp_takeoff_snapshot_v1(p_project_id uuid,p_takeoff_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
  -- #577 : métrés privés, comme l'estimation (Client propriétaire, gestionnaire affecté, Admin).
  if auth.uid() is null or not dao_private.btp_estimate_access(p_project_id) then
    raise exception using errcode='42501',message='project takeoff access required';
  end if;
  if p_takeoff_id is not null then
    select dao_private.btp_takeoff_payload(t.id) into result from public.btp_takeoffs t where t.id=p_takeoff_id and t.project_id=p_project_id;
    if result is null then raise exception using errcode='P0002',message='takeoff not found'; end if;
    return result;
  end if;
  return jsonb_build_object('projectId',p_project_id,'items',(select coalesce(jsonb_agg(dao_private.btp_takeoff_payload(t.id) order by t.updated_at desc,t.id),'[]'::jsonb)
    from public.btp_takeoffs t where t.project_id=p_project_id));
end;
$$;

drop policy btp_takeoffs_read on public.btp_takeoffs;
drop policy btp_takeoff_revisions_read on public.btp_takeoff_revisions;
drop policy btp_takeoff_events_read on public.btp_takeoff_events;
create policy btp_takeoffs_read on public.btp_takeoffs for select to authenticated using (dao_private.btp_estimate_access(project_id));
create policy btp_takeoff_revisions_read on public.btp_takeoff_revisions for select to authenticated
using (exists(select 1 from public.btp_takeoffs t where t.id=takeoff_id and dao_private.btp_estimate_access(t.project_id)));
create policy btp_takeoff_events_read on public.btp_takeoff_events for select to authenticated
using (exists(select 1 from public.btp_takeoffs t where t.id=takeoff_id and dao_private.btp_estimate_access(t.project_id)));

-- Estimation (#551) : occurrences du chantier et lots réels.
create or replace function dao_private.btp_estimate_compute(p_project_id uuid,p_input jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare
  v_mode text:=coalesce(p_input->>'mode','reference');
  v_ref date; v_private boolean; v_scope boolean; v_takeoffs boolean;
  v_gov uuid; v_gov_name text; v_version public.btp_catalog_versions;
  v_raw jsonb:='[]'::jsonb; v_keys text[]:='{}'; v_lines jsonb:='[]'::jsonb; v_missing jsonb:='[]'::jsonb;
  item jsonb; v_work record; v_scope_key text; v_kind text; v_value numeric; v_unit text; v_qty numeric; v_qty_micro numeric;
  v_status text; v_codes text[]; v_warn text[]; v_qsource jsonb; v_cands jsonb; v_best int; v_has_composite boolean;
  v_line jsonb; v_ht_min bigint; v_ht_max bigint; v_ttc_min bigint; v_ttc_max bigint; v_ht_ok boolean; v_ttc_ok boolean;
  v_comp text; c record; v_tk record; v_has_takeoffs boolean:=to_regclass('public.btp_takeoffs') is not null;
  v_wi record; v_req uuid; v_req_title text; v_req_order int; v_sub uuid; v_sub_title text; v_sub_ord int; v_ctx jsonb;
  v_total int:=0; v_priced int:=0; v_complete int:=0; v_coverage text; v_totals jsonb; v_by_lot jsonb; v_inputs jsonb; v_reason text;
begin
  if v_mode not in ('reference','simulation') then raise exception using errcode='22023',message='invalid estimate mode'; end if;
  if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('projectId','estimateId','expectedRevision','label','mode','referenceDate',
    'includePrivateAssumptions','includeAssistantScope','includeValidatedTakeoffs','lines','note')) then
    raise exception using errcode='22023',message='unexpected estimate field'; end if;
  foreach v_kind in array array['includePrivateAssumptions','includeAssistantScope','includeValidatedTakeoffs'] loop
    if p_input ? v_kind and jsonb_typeof(p_input->v_kind)<>'boolean' then raise exception using errcode='22023',message='boolean option expected'; end if;
  end loop;
  v_private:=coalesce((p_input->>'includePrivateAssumptions')::boolean,false);
  v_scope:=coalesce((p_input->>'includeAssistantScope')::boolean,true);
  v_takeoffs:=coalesce((p_input->>'includeValidatedTakeoffs')::boolean,true);
  if v_mode='simulation' and v_private then raise exception using errcode='22023',message='simulation never mixes private assumptions'; end if;
  v_ref:=coalesce(dao_private.btp_parse_date(p_input->>'referenceDate'),current_date);
  if p_input ? 'lines' and jsonb_typeof(p_input->'lines')<>'array' then raise exception using errcode='22023',message='lines must be an array'; end if;
  if jsonb_array_length(coalesce(p_input->'lines','[]'::jsonb))>200 then raise exception using errcode='22023',message='too many lines'; end if;

  select pv.governorate_id,g.name_fr into v_gov,v_gov_name from public.project_versions pv left join public.governorates g on g.id=pv.governorate_id
    where pv.project_id=p_project_id order by pv.version_no desc limit 1;
  select * into v_version from public.btp_catalog_versions where country_code='TN' and status='published';
  if not found then raise exception using errcode='P0002',message='no published BTP catalogue'; end if;

  -- a) lignes explicites
  for item in select x from jsonb_array_elements(coalesce(p_input->'lines','[]'::jsonb)) x loop
    if jsonb_typeof(item)<>'object' or exists(select 1 from jsonb_object_keys(item) k where k not in ('workId','scopeKey','quantity','source')) then
      raise exception using errcode='22023',message='invalid estimate line'; end if;
    if coalesce(item->>'workId','') !~ '^[0-9a-fA-F-]{36}$' then raise exception using errcode='22023',message='invalid work id'; end if;
    if not exists(select 1 from public.btp_works w where w.id=(item->>'workId')::uuid and w.catalog_version_id=v_version.id and w.active) then
      raise exception using errcode='22023',message='work is not in the published catalogue'; end if;
    v_scope_key:=coalesce(nullif(item->>'scopeKey',''),'default');
    if v_scope_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,79}$' then raise exception using errcode='22023',message='invalid scope key'; end if;
    if lower(item->>'workId')||'/'||v_scope_key = any(v_keys) then raise exception using errcode='22023',message='duplicate estimate line'; end if;
    v_kind:=coalesce(item->'source'->>'kind','none');
    if item ? 'source' and (jsonb_typeof(item->'source')<>'object' or exists(select 1 from jsonb_object_keys(item->'source') k where k not in ('kind','reference','takeoffId'))) then
      raise exception using errcode='22023',message='invalid quantity source'; end if;
    if v_kind='declared' then
      if jsonb_typeof(item->'quantity')<>'object' or coalesce(item->'quantity'->>'value','') !~ '^[0-9]{1,12}(\.[0-9]{1,6})?$' or (item->'quantity'->>'value')::numeric<=0 then
        raise exception using errcode='22023',message='declared quantity must be a positive decimal string'; end if;
      if length(btrim(coalesce(item->'source'->>'reference','')))<2 or length(item->'source'->>'reference')>300 then
        raise exception using errcode='22023',message='declared quantity needs a reference'; end if;
      if exists(select 1 from jsonb_object_keys(item->'quantity') k where k not in ('value','unit')) then raise exception using errcode='22023',message='invalid quantity'; end if;
      if item->'quantity'->>'unit' is not null and item->'quantity'->>'unit'<>(select w.unit_code from public.btp_works w where w.id=(item->>'workId')::uuid and w.catalog_version_id=v_version.id) then
        raise exception using errcode='22023',message='declared unit differs from the work unit; no implicit conversion'; end if;
    elsif v_kind='takeoff' then
      if item ? 'quantity' then raise exception using errcode='22023',message='takeoff quantities are read from the validated takeoff'; end if;
      if coalesce(item->'source'->>'takeoffId','') !~ '^[0-9a-fA-F-]{36}$' then raise exception using errcode='22023',message='invalid takeoff id'; end if;
      if not v_has_takeoffs then raise exception using errcode='22023',message='takeoff engine (#548) is not installed'; end if;
    elsif v_kind='none' then
      if item ? 'quantity' then raise exception using errcode='22023',message='a quantity needs a source'; end if;
    else raise exception using errcode='22023',message='invalid quantity source kind'; end if;
    v_keys:=v_keys||(lower(item->>'workId')||'/'||v_scope_key);
    v_raw:=v_raw||jsonb_build_array(jsonb_build_object('workId',lower(item->>'workId'),'scopeKey',v_scope_key,'origin','explicit',
      'source',case v_kind when 'declared' then jsonb_build_object('kind','declared','reference',btrim(item->'source'->>'reference'))
        when 'takeoff' then jsonb_build_object('kind','takeoff','takeoffId',lower(item->'source'->>'takeoffId')) else jsonb_build_object('kind','none') end,
      'declaredValue',case when v_kind='declared' then item->'quantity'->>'value' end));
  end loop;
  -- b) métrés validés du chantier (#548), lus par contrat si le moteur est installé
  if v_takeoffs and v_has_takeoffs then
    -- #577 : un métré validé rattaché à une occurrence donne sa propre ligne (jamais dédoublonnée par ouvrage) ;
    -- un ancien métré non rattaché garde l'ancienne clé ouvrage/périmètre. Occurrence retirée ou lot retiré : ignoré.
    for v_tk in select t.id,t.work_id,t.scope_key,t.project_work_item_id from public.btp_takeoffs t
        left join public.project_work_items pi on pi.id=t.project_work_item_id
        left join public.project_requests pr on pr.id=pi.request_id
        where t.project_id=p_project_id and t.validated_revision is not null
          and (t.project_work_item_id is null or (pi.status='active' and pr.status<>'withdrawn'))
        order by t.work_id,t.scope_key,t.id loop
      -- Métré rattaché : toujours sa ligne (un métré = une ligne), sauf s'il est déjà cité explicitement par son id.
      -- Il n'est jamais comparé à la clé ouvrage/périmètre, qui ne distingue pas deux lots.
      if v_tk.project_work_item_id is not null then
        if not exists(select 1 from jsonb_array_elements(v_raw) x where x->'source'->>'takeoffId'=v_tk.id::text) then
          v_raw:=v_raw||jsonb_build_array(jsonb_build_object('workId',v_tk.work_id,'scopeKey',v_tk.scope_key,'origin','validated_takeoff','workItemId',v_tk.project_work_item_id,'source',jsonb_build_object('kind','takeoff','takeoffId',v_tk.id)));
        end if;
      -- Ancien métré non rattaché : compté seulement si l'ouvrage n'a aucune occurrence active dans le chantier
      -- (sinon il est « à rattacher » et ne doit ni masquer ni doubler la quantité d'une occurrence).
      elsif not ((v_tk.work_id::text)||'/'||v_tk.scope_key = any(v_keys))
        and not exists(select 1 from public.project_work_items i where i.project_id=p_project_id and i.work_id=v_tk.work_id and i.status='active')
        and not exists(select 1 from jsonb_array_elements(v_raw) x where x->'source'->>'takeoffId'=v_tk.id::text) then
        v_keys:=v_keys||((v_tk.work_id::text)||'/'||v_tk.scope_key);
        v_raw:=v_raw||jsonb_build_array(jsonb_build_object('workId',v_tk.work_id,'scopeKey',v_tk.scope_key,'origin','validated_takeoff','unlinked',true,'source',jsonb_build_object('kind','takeoff','takeoffId',v_tk.id)));
      end if;
    end loop;
  end if;
  -- c) occurrences d'ouvrage du chantier (#577 : assistant, saisie manuelle, reprise) sans métré validé :
  -- une ligne par occurrence, sans quantité (dédoublonnage par occurrence, jamais par ouvrage).
  if v_scope then
    for v_wi in select i.id,i.work_id,i.label from public.project_work_items i join public.project_requests r on r.id=i.request_id
        where i.project_id=p_project_id and i.status='active' and r.status<>'withdrawn' order by r.created_at,r.id,i.ordinal,i.id loop
      if not exists(select 1 from jsonb_array_elements(v_raw) x where x->>'workItemId'=v_wi.id::text) then
        v_raw:=v_raw||jsonb_build_array(jsonb_build_object('workId',v_wi.work_id,'scopeKey','default','origin','work_item','workItemId',v_wi.id,
          'source',jsonb_build_object('kind','none')));
      end if;
    end loop;
  end if;

  -- d) évaluation ligne par ligne, ordre canonique du référentiel
  for item in select r.x from jsonb_array_elements(v_raw) r(x)
    left join public.project_work_items pi on pi.id=(r.x->>'workItemId')::uuid
    left join public.project_requests pr on pr.id=pi.request_id
    left join public.btp_works w on w.id=(r.x->>'workId')::uuid and w.catalog_version_id=v_version.id and w.active
    left join public.btp_sub_lots s on s.id=w.sub_lot_id and s.catalog_version_id=w.catalog_version_id
    left join public.btp_lots l on l.id=s.lot_id and l.catalog_version_id=s.catalog_version_id
    order by pr.created_at nulls last,pr.id nulls last,pi.ordinal nulls last,l.position nulls last,s.position nulls last,w.position nulls last,r.x->>'workId',r.x->>'scopeKey' loop
    v_total:=v_total+1; v_reason:=null; v_codes:='{}'; v_warn:='{}'; v_qty:=null; v_qty_micro:=null; v_cands:='[]'::jsonb; v_qsource:=item->'source';
    -- contexte réel du chantier : lot (project_requests) et sous-lot officiel facultatif de la version courante
    v_req:=null; v_req_title:=null; v_req_order:=null; v_sub:=null; v_sub_title:=null; v_sub_ord:=null;
    if item->>'workItemId' is not null then
      select pi.request_id,rv.title,(select count(*) from public.project_requests r2 where r2.project_id=p_project_id and (r2.created_at,r2.id)<(pr.created_at,pr.id)),
             sv.sub_lot_id,sv.title,sv.ordinal
        into v_req,v_req_title,v_req_order,v_sub,v_sub_title,v_sub_ord
        from public.project_work_items pi join public.project_requests pr on pr.id=pi.request_id
        join lateral (select x.* from public.project_request_versions x where x.request_id=pi.request_id order by x.version_no desc limit 1) rv on true
        left join public.request_sub_lot_versions sv on sv.request_version_id=rv.id and sv.sub_lot_id=pi.sub_lot_id
        where pi.id=(item->>'workItemId')::uuid;
    end if;
    v_ctx:=jsonb_build_object('workItemId',item->>'workItemId','requestId',v_req,'requestTitle',v_req_title,'lotOrder',v_req_order,
      'projectSubLotId',v_sub,'projectSubLotTitle',v_sub_title,'projectSubLotOrdinal',v_sub_ord,'unlinked',coalesce((item->>'unlinked')::boolean,false),
      'itemLabel',(select pi.label from public.project_work_items pi where pi.id=(item->>'workItemId')::uuid));
    select w.id,w.code,w.label_fr,w.unit_code,s.id sub_lot_id,s.label_fr sub_lot_label,l.id lot_id,l.code lot_code,l.label_fr lot_label into v_work
      from public.btp_works w join public.btp_sub_lots s on s.id=w.sub_lot_id and s.catalog_version_id=w.catalog_version_id
      join public.btp_lots l on l.id=s.lot_id and l.catalog_version_id=s.catalog_version_id
      where w.id=(item->>'workId')::uuid and w.catalog_version_id=v_version.id and w.active;
    if not found then
      v_reason:=case when item->>'workId' is null then 'custom_work_without_catalog_reference' else 'work_not_in_catalog' end;
      v_lines:=v_lines||jsonb_build_array(jsonb_build_object('workId',item->>'workId','workLabel',v_ctx->>'itemLabel','scopeKey',item->>'scopeKey','origin',item->>'origin','status','missing',
        'missing',jsonb_build_array(v_reason),'quantitySource',v_qsource,'quantity',null,'totals',jsonb_build_object('htMinMinor',null,'htMaxMinor',null,'ttcMinMinor',null,'ttcMaxMinor',null))||v_ctx);
      v_missing:=v_missing||jsonb_build_array(jsonb_build_object('workId',item->>'workId','workLabel',v_ctx->>'itemLabel','workItemId',item->>'workItemId','scopeKey',item->>'scopeKey','codes',jsonb_build_array(v_reason)));
      v_reason:=null;
      continue;
    end if;
    -- quantité
    if v_qsource->>'kind'='declared' then
      v_qty:=(item->>'declaredValue')::numeric;
      v_warn:=v_warn||'declared_quantity_not_validated'::text;
    elsif v_qsource->>'kind'='takeoff' then
      execute 'select t.project_id,t.work_id,t.validated_revision,t.current_revision,r.calculation_status,r.justification->''result''->>''value'' as value,r.justification->''result''->>''unit'' as unit
        from public.btp_takeoffs t left join public.btp_takeoff_revisions r on r.takeoff_id=t.id and r.revision=t.validated_revision where t.id=$1'
        into v_tk using (v_qsource->>'takeoffId')::uuid;
      if v_tk.project_id is distinct from p_project_id or v_tk.work_id is distinct from v_work.id then
        raise exception using errcode='22023',message='takeoff does not belong to this project and work'; end if;
      v_qsource:=v_qsource||jsonb_build_object('revision',v_tk.validated_revision);
      if v_tk.validated_revision is null or v_tk.calculation_status is distinct from 'calculated' or v_tk.value is null then v_codes:=v_codes||'quantity_not_validated'::text;
      elsif v_tk.unit is distinct from v_work.unit_code then v_codes:=v_codes||'quantity_unit_mismatch'::text;
      else v_qty:=v_tk.value::numeric;
        if v_tk.current_revision>v_tk.validated_revision then v_warn:=v_warn||'newer_takeoff_revision_not_validated'::text; end if;
      end if;
    else v_codes:=v_codes||'quantity_missing'::text;
    end if;
    if v_qty is not null then
      v_qty_micro:=v_qty*1000000;
      if v_qty<=0 or v_qty_micro<>trunc(v_qty_micro) then v_codes:=v_codes||'quantity_precision_unsupported'::text; v_qty:=null; v_qty_micro:=null; end if;
    end if;
    -- tarifs applicables
    select min(case when i.price_kind='private_assumption' then 1 when i.governorate_id is not null then 2 else 3 end),
           bool_or(i.component='composite') into v_best,v_has_composite
      from public.btp_price_items i
      join public.btp_price_item_revisions r on r.item_id=i.id and r.revision=case when i.price_kind='private_assumption' then i.current_revision else i.verified_revision end
      left join public.btp_price_sources s on s.id=i.source_id
      where i.work_id=v_work.id and i.unit_code=v_work.unit_code and i.status<>'retired' and i.country_code='TN'
        and (i.governorate_id is null or i.governorate_id=v_gov) and r.currency='TND'
        and r.valid_from<=v_ref and (r.valid_to is null or r.valid_to>=v_ref)
        and ((i.price_kind='observed' and i.verified_revision is not null and s.data_nature=case when v_mode='simulation' then 'fictitious_test' else 'real' end)
          or (i.price_kind='private_assumption' and v_private and i.project_id=p_project_id));
    if v_best is not null then
      select bool_or(i.component='composite') into v_has_composite from public.btp_price_items i
        join public.btp_price_item_revisions r on r.item_id=i.id and r.revision=case when i.price_kind='private_assumption' then i.current_revision else i.verified_revision end
        left join public.btp_price_sources s on s.id=i.source_id
        where i.work_id=v_work.id and i.unit_code=v_work.unit_code and i.status<>'retired' and i.country_code='TN'
          and (i.governorate_id is null or i.governorate_id=v_gov) and r.currency='TND' and r.valid_from<=v_ref and (r.valid_to is null or r.valid_to>=v_ref)
          and ((i.price_kind='observed' and i.verified_revision is not null and s.data_nature=case when v_mode='simulation' then 'fictitious_test' else 'real' end)
            or (i.price_kind='private_assumption' and v_private and i.project_id=p_project_id))
          and v_best=case when i.price_kind='private_assumption' then 1 when i.governorate_id is not null then 2 else 3 end;
      for c in
        with base as (
          select i.id,i.price_kind,i.component,i.governorate_id,r.revision,r.amount_min_minor,r.amount_max_minor,r.tax_basis,r.vat_rate_bp,r.includes,
            r.observed_on,r.valid_from,r.valid_to,r.source_locator,r.conditions_fr,s.id source_id,s.code source_code,s.name source_name,s.publisher,s.uri,s.license_note,s.data_nature
          from public.btp_price_items i
          join public.btp_price_item_revisions r on r.item_id=i.id and r.revision=case when i.price_kind='private_assumption' then i.current_revision else i.verified_revision end
          left join public.btp_price_sources s on s.id=i.source_id
          where i.work_id=v_work.id and i.unit_code=v_work.unit_code and i.status<>'retired' and i.country_code='TN'
            and (i.governorate_id is null or i.governorate_id=v_gov) and r.currency='TND' and r.valid_from<=v_ref and (r.valid_to is null or r.valid_to>=v_ref)
            and ((i.price_kind='observed' and i.verified_revision is not null and s.data_nature=case when v_mode='simulation' then 'fictitious_test' else 'real' end)
              or (i.price_kind='private_assumption' and v_private and i.project_id=p_project_id))
            and v_best=case when i.price_kind='private_assumption' then 1 when i.governorate_id is not null then 2 else 3 end
            and (i.component='composite')=v_has_composite)
        select b.* from base b where b.observed_on=(select max(x.observed_on) from base x where x.component=b.component)
        order by b.component,b.id
      loop
        v_cands:=v_cands||jsonb_build_array(jsonb_build_object('itemId',c.id,'revision',c.revision,'priceKind',c.price_kind,'component',c.component,
          'zone',case when c.price_kind='private_assumption' then 'project' when c.governorate_id is null then 'national' else 'governorate' end,
          'amountMinMinor',c.amount_min_minor,'amountMaxMinor',c.amount_max_minor,'taxBasis',c.tax_basis,'vatRateBp',c.vat_rate_bp,
          'includes',to_jsonb(c.includes),'observedOn',c.observed_on,'validFrom',c.valid_from,'validTo',c.valid_to,'sourceLocator',c.source_locator,
          'conditions',c.conditions_fr,'source',case when c.source_id is null then null else jsonb_build_object('id',c.source_id,'code',c.source_code,'name',c.source_name,
            'publisher',c.publisher,'uri',c.uri,'licenseNote',c.license_note,'dataNature',c.data_nature) end,
          'totalHtMinMinor',dao_private.btp_estimate_amount(v_qty_micro,c.amount_min_minor,c.tax_basis,c.vat_rate_bp,'HT'),
          'totalHtMaxMinor',dao_private.btp_estimate_amount(v_qty_micro,c.amount_max_minor,c.tax_basis,c.vat_rate_bp,'HT'),
          'totalTtcMinMinor',dao_private.btp_estimate_amount(v_qty_micro,c.amount_min_minor,c.tax_basis,c.vat_rate_bp,'TTC'),
          'totalTtcMaxMinor',dao_private.btp_estimate_amount(v_qty_micro,c.amount_max_minor,c.tax_basis,c.vat_rate_bp,'TTC')));
        if c.observed_on<v_ref-365 then v_warn:=v_warn||'price_observation_older_than_12_months'::text; end if;
      end loop;
    else
      -- diagnostic honnête de l'absence de tarif
      select case
        when bool_or(r.currency<>'TND') and not bool_or(r.currency='TND') then 'price_currency_without_sourced_rate'
        when bool_or(r.valid_from>v_ref or (r.valid_to is not null and r.valid_to<v_ref)) then 'price_out_of_validity_period'
        else null end into v_reason
        from public.btp_price_items i join public.btp_price_item_revisions r on r.item_id=i.id and r.revision=coalesce(i.verified_revision,0)
        left join public.btp_price_sources s on s.id=i.source_id
        where i.work_id=v_work.id and i.unit_code=v_work.unit_code and i.status<>'retired' and i.price_kind='observed'
          and (i.governorate_id is null or i.governorate_id=v_gov) and s.data_nature=case when v_mode='simulation' then 'fictitious_test' else 'real' end;
      if v_reason is null and exists(select 1 from public.btp_price_items i where i.work_id=v_work.id and i.unit_code<>v_work.unit_code and i.status='verified') then
        v_reason:='price_unit_differs_from_work_unit'; end if;
      v_codes:=v_codes||coalesce(v_reason,'price_missing');
    end if;
    -- agrégation de la ligne : fourchette sur les sources ex aequo, somme des composantes
    v_ht_min:=null;v_ht_max:=null;v_ttc_min:=null;v_ttc_max:=null;v_ht_ok:=false;v_ttc_ok:=false;
    if v_qty is not null and jsonb_array_length(v_cands)>0 then
      select bool_and(ok_ht),bool_and(ok_ttc),sum(hmin),sum(hmax),sum(tmin),sum(tmax) into v_ht_ok,v_ttc_ok,v_ht_min,v_ht_max,v_ttc_min,v_ttc_max from (
        select x->>'component' comp,
          bool_and(x->>'totalHtMinMinor' is not null) ok_ht,bool_and(x->>'totalTtcMinMinor' is not null) ok_ttc,
          min((x->>'totalHtMinMinor')::bigint) hmin,max((x->>'totalHtMaxMinor')::bigint) hmax,
          min((x->>'totalTtcMinMinor')::bigint) tmin,max((x->>'totalTtcMaxMinor')::bigint) tmax
        from jsonb_array_elements(v_cands) x group by x->>'component') g;
      if not v_ht_ok then v_ht_min:=null; v_ht_max:=null; v_warn:=v_warn||'ht_not_derivable_without_explicit_vat_rate'::text; end if;
      if not v_ttc_ok then v_ttc_min:=null; v_ttc_max:=null; v_warn:=v_warn||'ttc_not_derivable_without_explicit_vat_rate'::text; end if;
      v_status:=case when v_has_composite then 'priced' else 'priced_components' end;
      if not v_has_composite then v_warn:=v_warn||'components_only_other_components_may_be_missing'::text; end if;
      if (select count(distinct x->>'amountMinMinor')+count(distinct x->>'amountMaxMinor') from jsonb_array_elements(v_cands) x)>2 then v_warn:=v_warn||'several_sources_range'::text; end if;
    else
      v_status:='missing';
      if v_qty is not null and jsonb_array_length(v_cands)=0 then null; end if;
      if v_qty is null and jsonb_array_length(v_cands)>0 then v_warn:=v_warn||'price_available_quantity_missing'::text; end if;
    end if;
    if v_status in ('priced','priced_components') then v_priced:=v_priced+1; end if;
    if v_status='priced' then v_complete:=v_complete+1; end if;
    v_line:=jsonb_build_object('workId',v_work.id,'workCode',v_work.code,'workLabel',v_work.label_fr,'unitCode',v_work.unit_code,
      'lotId',v_work.lot_id,'lotCode',v_work.lot_code,'lotLabel',v_work.lot_label,'subLotId',v_work.sub_lot_id,'subLotLabel',v_work.sub_lot_label,
      'scopeKey',item->>'scopeKey','origin',item->>'origin','status',v_status,
      'quantity',case when v_qty is null then null else jsonb_build_object('value',v_qty::text,'unit',v_work.unit_code) end,'quantitySource',v_qsource,
      'candidates',v_cands,'totals',jsonb_build_object('htMinMinor',v_ht_min,'htMaxMinor',v_ht_max,'ttcMinMinor',v_ttc_min,'ttcMaxMinor',v_ttc_max),
      'missing',to_jsonb(v_codes),'warnings',to_jsonb(array(select distinct w from unnest(v_warn) w order by w)),
      'formula','quantité × prix unitaire (arrondi au millime, demi supérieur)')||v_ctx;
    v_lines:=v_lines||jsonb_build_array(v_line);
    if v_status='missing' then
      v_missing:=v_missing||jsonb_build_array(jsonb_build_object('workId',v_work.id,'workLabel',v_work.label_fr,'unitCode',v_work.unit_code,'workItemId',item->>'workItemId','scopeKey',item->>'scopeKey','codes',to_jsonb(v_codes)));
    end if;
  end loop;

  v_coverage:=case when v_total>0 and v_complete=v_total then 'complete' when v_priced=0 then 'unavailable' else 'partial' end;
  select jsonb_build_object(
      'scope',case when v_coverage='complete' then 'complete' when v_coverage='partial' then 'priced_lines_only' else 'none' end,
      'htMinMinor',case when bool_and(l->'totals'->>'htMinMinor' is not null) then sum((l->'totals'->>'htMinMinor')::bigint) end,
      'htMaxMinor',case when bool_and(l->'totals'->>'htMaxMinor' is not null) then sum((l->'totals'->>'htMaxMinor')::bigint) end,
      'ttcMinMinor',case when bool_and(l->'totals'->>'ttcMinMinor' is not null) then sum((l->'totals'->>'ttcMinMinor')::bigint) end,
      'ttcMaxMinor',case when bool_and(l->'totals'->>'ttcMaxMinor' is not null) then sum((l->'totals'->>'ttcMaxMinor')::bigint) end,
      'linesWithoutHt',count(*) filter (where l->'totals'->>'htMinMinor' is null),
      'linesWithoutTtc',count(*) filter (where l->'totals'->>'ttcMinMinor' is null))
    into v_totals from jsonb_array_elements(v_lines) l where l->>'status' in ('priced','priced_components');
  if v_priced=0 then v_totals:=jsonb_build_object('scope','none','htMinMinor',null,'htMaxMinor',null,'ttcMinMinor',null,'ttcMaxMinor',null,'linesWithoutHt',0,'linesWithoutTtc',0); end if;
  -- #577 : regroupement par lot RÉEL du chantier puis sous-lot officiel facultatif ; sous-totaux séparés,
  -- uniquement des montants (jamais de somme de m², m³ et unités). Lignes non rattachées : groupe à part.
  select coalesce(jsonb_agg(g order by g->>'position',g->>'lotId' nulls last),'[]'::jsonb) into v_by_lot from (
    select jsonb_build_object('lotId',q.rid,'requestId',q.rid,'lotCode',null,
      'lotLabel',coalesce(min(q.l->>'requestTitle'),'Ouvrages non rattachés à un lot du chantier'),
      'position',lpad(coalesce(min((q.l->>'lotOrder')::int),999999)::text,6,'0'),
      'totalLines',count(*),'pricedLines',count(*) filter (where q.l->>'status' in ('priced','priced_components')),
      'htMinMinor',case when bool_and(q.l->'totals'->>'htMinMinor' is not null) filter (where q.l->>'status'<>'missing') then sum((q.l->'totals'->>'htMinMinor')::bigint) end,
      'htMaxMinor',case when bool_and(q.l->'totals'->>'htMaxMinor' is not null) filter (where q.l->>'status'<>'missing') then sum((q.l->'totals'->>'htMaxMinor')::bigint) end,
      'ttcMinMinor',case when bool_and(q.l->'totals'->>'ttcMinMinor' is not null) filter (where q.l->>'status'<>'missing') then sum((q.l->'totals'->>'ttcMinMinor')::bigint) end,
      'ttcMaxMinor',case when bool_and(q.l->'totals'->>'ttcMaxMinor' is not null) filter (where q.l->>'status'<>'missing') then sum((q.l->'totals'->>'ttcMaxMinor')::bigint) end,
      'subLots',(select coalesce(jsonb_agg(sg order by sg->>'position'),'[]'::jsonb) from (
        select jsonb_build_object('subLotId',s->>'projectSubLotId','title',coalesce(min(s->>'projectSubLotTitle'),'Directement dans le lot'),
          'position',lpad(coalesce(min((s->>'projectSubLotOrdinal')::int)+1,0)::text,6,'0'),
          'totalLines',count(*),'pricedLines',count(*) filter (where s->>'status' in ('priced','priced_components')),
          'htMinMinor',case when bool_and(s->'totals'->>'htMinMinor' is not null) filter (where s->>'status'<>'missing') then sum((s->'totals'->>'htMinMinor')::bigint) end,
          'htMaxMinor',case when bool_and(s->'totals'->>'htMaxMinor' is not null) filter (where s->>'status'<>'missing') then sum((s->'totals'->>'htMaxMinor')::bigint) end,
          'ttcMinMinor',case when bool_and(s->'totals'->>'ttcMinMinor' is not null) filter (where s->>'status'<>'missing') then sum((s->'totals'->>'ttcMinMinor')::bigint) end,
          'ttcMaxMinor',case when bool_and(s->'totals'->>'ttcMaxMinor' is not null) filter (where s->>'status'<>'missing') then sum((s->'totals'->>'ttcMaxMinor')::bigint) end) sg
        from jsonb_array_elements(v_lines) s where s->>'requestId' is not distinct from q.rid and q.rid is not null group by s->>'projectSubLotId') y)) g
    from (select x l,x->>'requestId' rid from jsonb_array_elements(v_lines) x) q group by q.rid) z;

  v_inputs:=jsonb_build_object('mode',v_mode,'referenceDate',v_ref,'includePrivateAssumptions',v_private,'includeAssistantScope',v_scope,
    'includeValidatedTakeoffs',v_takeoffs,'lines',v_raw);
  return jsonb_build_object('inputs',v_inputs,'result',jsonb_build_object(
    'engine','dao-estimate-v1','nonContractual',true,'mode',v_mode,'referenceDate',v_ref,'currency','TND','countryCode','TN',
    'governorateId',v_gov,'governorate',v_gov_name,'catalogVersion',jsonb_build_object('id',v_version.id,'code',v_version.code),
    'takeoffEngineAvailable',v_has_takeoffs,
    'coverage',jsonb_build_object('status',v_coverage,'totalLines',v_total,'pricedLines',v_priced,'completeLines',v_complete,'missingLines',v_total-v_priced),
    'totals',v_totals,'byLot',v_by_lot,'lines',v_lines,'missing',v_missing,
    'warnings',to_jsonb(array_remove(array['non_contractual_estimate',
      case when v_mode='simulation' then 'simulation_fictitious_test_data' end,
      case when v_private then 'private_assumptions_requested' end,
      case when v_coverage<>'complete' then 'incomplete_estimate_total_is_not_a_budget' end],null)),
    'grouping','project_lots','rules',jsonb_build_object('version','estimate-rules-v2','selection',jsonb_build_array(
      'Une ligne par occurrence d''ouvrage du chantier (lot réel, sous-lot facultatif) ou par métré validé de cette occurrence ; jamais de dédoublonnage par ouvrage.',
      'Ouvrage canonique et unité de l''ouvrage identiques ; aucune conversion d''unité.',
      'Tarif observé vérifié (non retiré) ou, sur demande explicite, hypothèse privée du chantier ; jamais un prix d''offre.',
      'Période de validité couvrant la date de référence ; devise TND (aucun taux de change sourcé).',
      'Priorité : hypothèse privée demandée, puis gouvernorat du chantier, puis national ; jamais un autre gouvernorat.',
      'Prix global (composite) prioritaire ; à défaut, somme des composantes publiées signalée partielle.',
      'Observation la plus récente ; plusieurs sources ex aequo donnent une fourchette min–max.',
      'Mode simulation : uniquement des sources de test fictives ; mode référence : uniquement des données réelles.'),
      'rounding','Total de ligne = quantité × prix unitaire, arrondi au millime (demi supérieur), en arithmétique entière.',
      'tax','HT et TTC calculés séparément ; conversion uniquement avec le taux de TVA explicite du tarif.',
      'freshness','Observation de plus de 12 mois avant la date de référence : avertissement, sans exclusion.')));
end;
$$;

-- Assistant (#543) : création atomique vers la liste commune ; entrée paramétrable.
create or replace function dao_private.save_project_assistant_draft_v1(
  p_draft_id uuid, p_expected_revision integer, p_kind text, p_command text, p_draft jsonb
) returns jsonb language plpgsql security definer set search_path='' as $$
declare v public.project_assistant_drafts; v_type text; v_description text; v_title text; v_governorate uuid; v_engine text;
begin
  if auth.uid() is null or not dao_private.account_active(auth.uid()) then
    raise exception using errcode='42501', message='active authentication required';
  end if;
  if p_kind not in ('analyze','edit') or p_draft is null or jsonb_typeof(p_draft) <> 'object'
     or (p_draft - array['projectType','description','title','governorateId','proposal','referential','engineMode']) <> '{}'::jsonb then
    raise exception using errcode='22023', message='invalid assistant draft';
  end if;
  v_type := p_draft->>'projectType'; v_description := btrim(coalesce(p_draft->>'description',''));
  v_title := btrim(coalesce(p_draft->>'title','')); v_engine := coalesce(p_draft->>'engineMode','rules');
  if nullif(p_draft->>'governorateId','') is not null then
    if p_draft->>'governorateId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception using errcode='22023', message='invalid governorate';
    end if;
    v_governorate := (p_draft->>'governorateId')::uuid;
  end if;
  if p_draft_id is null then
    if p_kind <> 'analyze' then raise exception using errcode='22023', message='draft required'; end if;
    -- #577 : l'entrée assistant peut être masquée par les Settings ; un brouillon existant reste utilisable.
    perform dao_private.require_setting('client.project_assistant', auth.uid(), 'client', null);
    insert into public.project_assistant_drafts(owner_id, project_type, description, title, governorate_id, proposal, referential, engine_mode)
    values (auth.uid(), v_type, v_description, v_title, v_governorate, p_draft->'proposal', p_draft->'referential', v_engine)
    returning * into v;
  else
    select * into v from public.project_assistant_drafts where id = p_draft_id and owner_id = auth.uid() for update;
    if v.id is null then raise exception using errcode='P0002', message='assistant draft not found'; end if;
    if v.status <> 'draft' then raise exception using errcode='23514', message='assistant draft is closed'; end if;
    if p_expected_revision is distinct from v.revision then raise exception using errcode='40001', message='assistant draft changed'; end if;
    update public.project_assistant_drafts set revision = v.revision + 1, updated_at = now(), project_type = v_type,
      description = v_description, title = v_title, governorate_id = v_governorate, proposal = p_draft->'proposal',
      referential = p_draft->'referential', engine_mode = v_engine
    where id = v.id returning * into v;
  end if;
  insert into public.project_assistant_draft_revisions(draft_id, owner_id, revision, kind, command, project_type, governorate_id, proposal)
  values (v.id, v.owner_id, v.revision, p_kind, left(nullif(btrim(p_command),''), 500), v.project_type, v.governorate_id, v.proposal);
  return to_jsonb(v) - 'creation_key';
end; $$;

create or replace function dao_private.create_project_from_assistant_draft_v1(p_draft_id uuid, p_creation_key text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  v public.project_assistant_drafts; v_project public.projects; v_request public.project_requests;
  v_request_version uuid; v_sub_lot uuid; v_trade uuid; v_lot jsonb; v_sub jsonb; v_items jsonb;
  v_lot_scope text; v_sub_scope text; v_ordinal integer; v_lots integer := 0;
begin
  if auth.uid() is null or not dao_private.account_active(auth.uid()) then
    raise exception using errcode='42501', message='active authentication required';
  end if;
  if not exists (select 1 from public.user_roles where user_id = auth.uid() and role = 'client') then
    raise exception using errcode='42501', message='client role required';
  end if;
  if p_creation_key is null or length(p_creation_key) not between 8 and 120 then
    raise exception using errcode='22023', message='creation key required';
  end if;
  select * into v from public.project_assistant_drafts where id = p_draft_id and owner_id = auth.uid() for update;
  if v.id is null then raise exception using errcode='P0002', message='assistant draft not found'; end if;
  if v.status = 'created' then
    return jsonb_build_object('projectId', v.created_project_id, 'created', false, 'lots', 0);
  end if;
  if v.status <> 'draft' then raise exception using errcode='23514', message='assistant draft is closed'; end if;
  if v.governorate_id is null then raise exception using errcode='23514', message='governorate required'; end if;

  select coalesce(jsonb_agg(item), '[]'::jsonb) into v_items
    from jsonb_array_elements(v.proposal->'items') item where (item->>'selected')::boolean is true;
  if not exists (select 1 from jsonb_array_elements(v_items) item where item->>'kind' = 'lot') then
    raise exception using errcode='23514', message='at least one lot required';
  end if;
  if exists (select 1 from jsonb_array_elements(v_items) item where
      coalesce(item->>'id','') !~ '^[A-Za-z0-9:_-]{1,80}$' or item->>'kind' not in ('lot','sub_lot','work')
      or length(btrim(coalesce(item->>'label',''))) not between 1 and 200
      or (item->>'kind' <> 'lot' and not exists (select 1 from jsonb_array_elements(v_items) parent
        where parent->>'id' = item->>'parentId' and parent->>'kind' = case item->>'kind' when 'sub_lot' then 'lot' else 'sub_lot' end))) then
    raise exception using errcode='23514', message='invalid assistant selection';
  end if;

  v_project := dao_private.create_project_draft(v.project_type, null::numeric, null::date, null::date, null::bigint, v.governorate_id, null::uuid, null::uuid);
  update public.project_versions set title = v.title,
    description = left(v.description || E'\n\nPérimètre préparé avec l’assistant D.A.O. à partir du référentiel '
      || coalesce(v.referential->>'provider','') || ' ' || coalesce(v.referential->>'catalogVersion','')
      || '. Aucun prix, quantité ni délai n’a été estimé.', 10000)
    where project_id = v_project.id and version_no = 1;

  for v_lot in select item from jsonb_array_elements(v_items) item where item->>'kind' = 'lot' loop
    select id into v_trade from public.trades where code = v_lot->>'tradeCode' and active;
    if v_trade is null then select id into v_trade from public.trades where code = 'general_contractor' and active; end if;
    if v_trade is null then raise exception using errcode='23514', message='trade unavailable'; end if;
    select string_agg('• ' || (sub->>'label'), E'\n' order by ord) into v_lot_scope
      from jsonb_array_elements(v_items) with ordinality s(sub, ord) where sub->>'parentId' = v_lot->>'id';
    v_lot_scope := coalesce(v_lot_scope, 'Périmètre à préciser avec les professionnels.')
      || E'\n\nÀ confirmer avec les professionnels : quantités, prix et délais non estimés.';
    v_request := dao_private.add_project_request(v_project.id, v_trade, left(v_lot->>'label', 200), v_lot_scope, null::bigint);
    select id into v_request_version from public.project_request_versions where request_id = v_request.id and version_no = 1;
    insert into public.project_assistant_scope_links(project_id, request_id, draft_id, referential_provider, referential_version, item_id, item_code, item_kind, item_label, unit, relevance)
    values (v_project.id, v_request.id, v.id, v.referential->>'provider', v.referential->>'catalogVersion', v_lot->>'id', v_lot->>'code', 'lot', v_lot->>'label', v_lot->>'unit', coalesce(v_lot->>'relevance','usual'));
    v_ordinal := 0;
    for v_sub in select sub from jsonb_array_elements(v_items) with ordinality s(sub, ord) where sub->>'parentId' = v_lot->>'id' and sub->>'kind' = 'sub_lot' order by ord loop
      select string_agg('• ' || (work->>'label') || case when work->>'relevance' in ('verify','unusual') or (work->>'tentative')::boolean is true then ' (à vérifier)' else '' end, E'\n' order by ord)
        into v_sub_scope from jsonb_array_elements(v_items) with ordinality w(work, ord) where work->>'parentId' = v_sub->>'id';
      insert into public.request_sub_lots(request_id, project_id) values (v_request.id, v_project.id) returning id into v_sub_lot;
      insert into public.request_sub_lot_versions(sub_lot_id, request_id, project_id, request_version_id, ordinal, title, scope, budget_millimes)
      values (v_sub_lot, v_request.id, v_project.id, v_request_version, v_ordinal, left(v_sub->>'label', 200),
        coalesce(v_sub_scope, 'Contenu à préciser avec les professionnels.'), null);
      v_ordinal := v_ordinal + 1;
      insert into public.project_assistant_scope_links(project_id, request_id, sub_lot_id, draft_id, referential_provider, referential_version, item_id, item_code, item_kind, item_label, unit, relevance)
      select v_project.id, v_request.id, v_sub_lot, v.id, v.referential->>'provider', v.referential->>'catalogVersion', x->>'id', x->>'code', x->>'kind', x->>'label', x->>'unit', coalesce(x->>'relevance','usual')
        from jsonb_array_elements(v_items) x where x->>'id' = v_sub->>'id' or x->>'parentId' = v_sub->>'id';
    end loop;
    v_lots := v_lots + 1;
  end loop;

  -- #577 : transcription atomique des ouvrages retenus vers la liste commune du chantier (idempotente par lien).
  perform dao_private.import_assistant_work_items_v1(v_project.id);

  update public.project_assistant_drafts set status = 'created', created_project_id = v_project.id, creation_key = p_creation_key,
    revision = v.revision + 1, updated_at = now() where id = v.id returning * into v;
  insert into public.project_assistant_draft_revisions(draft_id, owner_id, revision, kind, project_type, governorate_id, proposal)
  values (v.id, v.owner_id, v.revision, 'create', v.project_type, v.governorate_id, v.proposal);
  return jsonb_build_object('projectId', v_project.id, 'created', true, 'lots', v_lots);
end; $$;

create or replace function dao_private.btp_estimate_snapshot_v1(p_project_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
  if auth.uid() is null or not dao_private.btp_estimate_access(p_project_id) then raise exception using errcode='42501',message='project estimate access required'; end if;
  return jsonb_build_object('projectId',p_project_id,
    'governorate',(select jsonb_build_object('id',g.id,'name',g.name_fr) from public.project_versions pv join public.governorates g on g.id=pv.governorate_id where pv.project_id=p_project_id order by pv.version_no desc limit 1),
    'takeoffEngineAvailable',true,
    'takeoffs',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'workId',t.work_id,'workItemId',t.project_work_item_id,'scopeKey',t.scope_key,'label',t.label,'status',t.status,'validatedRevision',t.validated_revision,'currentRevision',t.current_revision) order by t.label,t.id),'[]'::jsonb)
      from public.btp_takeoffs t where t.project_id=p_project_id),
    -- #577 : ouvrages retenus = occurrences actives du chantier (assistant, saisie manuelle, reprise).
    'scopeWorks',(select coalesce(jsonb_agg(jsonb_build_object('workItemId',i.id,'workId',i.work_id,'label',i.label,'unit',i.unit_code,'requestId',i.request_id,'subLotId',i.sub_lot_id) order by i.request_id,i.ordinal,i.id),'[]'::jsonb)
      from public.project_work_items i join public.project_requests r on r.id=i.request_id where i.project_id=p_project_id and i.status='active' and r.status<>'withdrawn'),
    'estimates',(select coalesce(jsonb_agg(dao_private.btp_estimate_payload(e.id) order by e.updated_at desc,e.id),'[]'::jsonb) from public.btp_estimates e where e.project_id=p_project_id));
end;
$$;

-- ---------------------------------------------------------------------------------------------
-- Points d'entrée publics (JWT) et droits
-- ---------------------------------------------------------------------------------------------
create function public.project_work_items_snapshot_v1(p_project_id uuid) returns jsonb
language sql stable security invoker set search_path='' as $$ select dao_private.project_work_items_snapshot_v1($1); $$;
create function public.project_work_item_history_v1(p_item_id uuid) returns jsonb
language sql stable security invoker set search_path='' as $$ select dao_private.project_work_item_history_v1($1); $$;
create function public.project_work_item_command_v1(p_action text, p_input jsonb, p_idempotency_key text) returns jsonb
language sql security invoker set search_path='' as $$ select dao_private.project_work_item_command_v1($1, $2, $3); $$;

revoke all on function dao_private.project_work_item_identity_guard(), dao_private.project_work_item_lock_reason(uuid),
  dao_private.project_work_item_json(uuid), dao_private.project_work_items_snapshot_v1(uuid), dao_private.project_work_item_history_v1(uuid),
  dao_private.project_work_item_event(public.project_work_items, text, uuid, jsonb), dao_private.project_work_item_command_v1(text, jsonb, text),
  dao_private.publication_works_snapshot(), dao_private.import_assistant_work_items_v1(uuid), dao_private.link_legacy_takeoffs_v1(uuid)
  from public, anon, authenticated;
grant execute on function dao_private.project_work_items_snapshot_v1(uuid), dao_private.project_work_item_history_v1(uuid),
  dao_private.project_work_item_command_v1(text, jsonb, text) to authenticated, service_role;
grant execute on function dao_private.import_assistant_work_items_v1(uuid), dao_private.link_legacy_takeoffs_v1(uuid) to service_role;
revoke all on function public.project_work_items_snapshot_v1(uuid), public.project_work_item_history_v1(uuid),
  public.project_work_item_command_v1(text, jsonb, text) from public, anon;
grant execute on function public.project_work_items_snapshot_v1(uuid), public.project_work_item_history_v1(uuid),
  public.project_work_item_command_v1(text, jsonb, text) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------
-- Reprise idempotente des dossiers existants (lecture seule des sources append-only)
-- ---------------------------------------------------------------------------------------------
select dao_private.import_assistant_work_items_v1(null);
select dao_private.link_legacy_takeoffs_v1(null);

commit;
